(() => {
  let glossary = {};
  let timeline = { events: [] };

  const esc = value => String(value ?? '')
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;')
    .replaceAll("'", '&#039;');
  const route = () => location.hash.replace(/^#\/?/, '').split('/').filter(Boolean);
  const courses = () => { try { return state?.data?.courses || []; } catch { return []; } };
  const courseById = id => courses().find(course => course.id === id);
  const clean = value => String(value || '').toLocaleLowerCase('pt-BR').normalize('NFD').replace(/[\u0300-\u036f]/g, '');
  const tokens = value => clean(value).split(/[^a-z0-9]+/).filter(word => word.length >= 4);

  const GUIDE_RULES = [
    { match: /evolução humana/i, simple: 'A história humana não começa com uma fila de espécies que melhora até chegar ao Homo sapiens. Ela se parece mais com uma árvore cheia de ramos: espécies diferentes coexistiram, migraram e algumas chegaram a se cruzar.', anchor: 'Milhões de anos até cerca de 40 mil anos atrás, África e diferentes regiões da Eurásia.', detail: ['Homo sapiens surgiu na África e se dispersou em várias ondas.', 'Neandertais e denisovanos não foram simples etapas anteriores ao ser humano moderno. Eles foram populações humanas distintas.', 'Fósseis, DNA antigo, ferramentas e sítios arqueológicos precisam ser combinados porque nenhuma fonte conta a história inteira.'] },
    { match: /^Paleolítico$/i, simple: 'Durante quase toda a existência do Homo sapiens, ninguém vivia de agricultura. Grupos humanos caçavam, pescavam, coletavam plantas e se moviam de acordo com estações, recursos e relações sociais.', anchor: 'Cerca de 2,6 milhões de anos atrás até aproximadamente 10 mil a.C., com cronologias diferentes por região.', detail: ['Caçadores-coletores não formavam um único tipo de sociedade.', 'Mobilidade exigia conhecimento detalhado do ambiente e redes de troca entre grupos.', 'Arte rupestre, ferramentas e sepultamentos ajudam a reconstruir crenças e relações sociais, mas precisam ser interpretados com cautela.'] },
    { match: /^Neolítico$/i, simple: 'O Neolítico não foi o dia em que a humanidade decidiu virar agricultora. Foi um conjunto de mudanças lentas, ocorrido em lugares diferentes, no qual algumas populações passaram a cultivar plantas, criar animais e permanecer mais tempo em assentamentos.', anchor: 'A partir de cerca de 10 mil a.C. em algumas regiões, mas em datas muito diferentes ao redor do mundo.', detail: ['Agricultura surgiu de forma independente no Crescente Fértil, China, Nova Guiné, Mesoamérica, Andes e outras regiões.', 'Sedentarização podia ocorrer antes da agricultura e agricultura não significava automaticamente vida melhor.', 'Mais alimento armazenável também podia aumentar doença, trabalho, desigualdade e disputa por terra.'] },
    { match: /agricultura e domesticação/i, simple: 'Domesticar uma planta ou um animal significa alterar, geração após geração, a relação entre aquela espécie e os seres humanos. Isso muda dieta, paisagem, calendário de trabalho e até formas de propriedade.', anchor: 'Processos diferentes desde o fim do Pleistoceno e início do Holoceno.', detail: ['Trigo, arroz, milho, batata e mandioca exigem técnicas muito diferentes.', 'Armazenar produção cria novas possibilidades de troca, reserva, tributação e controle.', 'Ambiente importa, mas não determina sozinho a organização política de uma sociedade.'] },
    { match: /primeiras cidades/i, simple: 'Uma cidade é mais do que uma aldeia grande. Ela concentra população, atividades especializadas, circulação de bens, autoridades e espaços públicos. O ponto importante é entender como essas funções passaram a se combinar.', anchor: 'A partir do IV milênio a.C. em partes da Mesopotâmia, com outras urbanizações independentes em diferentes regiões.', detail: ['Uruk é um caso importante, mas não serve como modelo universal para toda urbanização.', 'Cidades podiam existir com graus muito diferentes de centralização política.', 'Arqueólogos observam tamanho, especialização, monumentalidade, redes de troca e organização do espaço.'] },
    { match: /formação do Estado/i, simple: 'Um Estado aparece quando instituições conseguem exercer autoridade de forma relativamente duradoura sobre pessoas e território. Isso envolve administração, cobrança de recursos, regras e algum tipo de coerção.', anchor: 'Processos variados desde o IV e III milênios a.C. em diferentes partes do mundo.', detail: ['Não existe uma única causa para o surgimento dos Estados.', 'Guerra, irrigação, comércio, população e controle de excedentes podem participar do processo em combinações diferentes.', 'Também é importante estudar quem tentou escapar, negociar ou resistir a essas formas de controle.'] },
    { match: /^Mesopotâmia$/i, simple: 'Mesopotâmia é o nome de uma região entre os rios Tigre e Eufrates. Ela não foi um país único. Ao longo de milhares de anos, cidades e impérios como Uruk, Ur, Akkad, Babilônia e Assíria dominaram partes diferentes desse espaço.', anchor: 'Principalmente atual Iraque e áreas vizinhas, do IV milênio a.C. ao primeiro milênio a.C.', detail: ['As primeiras cidades cresceram no sul, onde irrigação, templos, trabalho organizado e comércio tiveram grande importância.', 'A escrita cuneiforme começou ligada a registros administrativos e depois foi usada para leis, literatura, cartas e conhecimento.', 'Reis não governavam sozinhos: templos, palácios, famílias, comerciantes e elites locais disputavam recursos e autoridade.', 'O Código de Hamurábi é valioso, mas não deve ser lido como se fosse um código penal moderno aplicado de maneira uniforme.'] },
    { match: /Egito Antigo/i, simple: 'O Egito antigo durou milhares de anos, por isso não pode ser tratado como uma sociedade que nunca mudou. O Nilo ajudava a organizar agricultura e circulação, enquanto a monarquia apresentava o faraó como responsável pela ordem do mundo.', anchor: 'Vale do Nilo, aproximadamente de 3100 a.C. até a conquista romana em 30 a.C.', detail: ['Historiadores dividem a história egípcia em reinos e períodos intermediários para destacar fases de centralização e fragmentação.', 'Maat ligava justiça, equilíbrio e ordem cósmica à legitimidade do rei.', 'Egito manteve relações intensas com Núbia, Levante, Líbia e Mediterrâneo.', 'Pirâmides, tumbas e inscrições reais mostram muito sobre elites, mas documentos administrativos e arqueologia revelam aspectos diferentes da sociedade.'] },
    { match: /Fenícios|Levante/i, simple: 'O Levante era uma faixa de contato entre grandes potências e o Mediterrâneo. Cidades como Tiro, Sidon e Biblos enriqueceram com comércio marítimo, mas nunca formaram um único Estado chamado Fenícia.', anchor: 'Mediterrâneo oriental, sobretudo do II ao I milênio a.C.', detail: ['O nome fenício foi usado por outros povos para comunidades que possuíam identidades locais próprias.', 'Rotas marítimas ligaram o Levante a Chipre, Norte da África, Sicília, Península Ibérica e outros portos.', 'O alfabeto fenício foi uma das tradições que influenciaram alfabetos posteriores, inclusive o grego.'] },
    { match: /Império Persa|Aquemênida/i, simple: 'O Império Persa Aquemênida governou um território enorme sem tentar transformar todas as populações em uma cultura única. A administração combinava autoridades imperiais, impostos, estradas e elites locais.', anchor: 'Do vale do Indo ao Egito e à Anatólia, cerca de 550 a 330 a.C.', detail: ['Ciro, Dario e Xerxes governaram populações com línguas, religiões e tradições políticas diferentes.', 'Satrapias ajudavam a administrar regiões, mas sátrapas não eram governadores independentes.', 'As Guerras Persas são conhecidas principalmente por fontes gregas, por isso é importante comparar essas narrativas com inscrições e documentos persas.'] },
    { match: /hititas|amarna/i, simple: 'Antes do colapso da Idade do Bronze, Egito, Hititas, Babilônia, Assíria e outros reinos participavam de um sistema diplomático internacional. Reis trocavam cartas, presentes, princesas e ameaças.', anchor: 'Mediterrâneo oriental e Oriente Próximo, sobretudo séculos XV a XIII a.C.', detail: ['As cartas de Amarna revelam diplomacia entre grandes reis e governantes menores.', 'O sistema dependia de rotas comerciais, metais, cavalos e redes palaciais.', 'Isso ajuda a entender por que a crise por volta de 1200 a.C. teve efeitos tão amplos.'] },
    { match: /Povos do Mar|colapso da Idade do Bronze/i, simple: 'Por volta de 1200 a.C., vários palácios, cidades e reinos do Mediterrâneo oriental entraram em crise. Os chamados Povos do Mar aparecem em fontes egípcias, mas não explicam sozinhos o colapso.', anchor: 'Mediterrâneo oriental e Oriente Próximo, aproximadamente 1250 a 1100 a.C.', detail: ['Destruições, migrações, conflitos internos, mudanças climáticas e quebra de redes comerciais podem ter atuado ao mesmo tempo.', 'Povos do Mar é um rótulo egípcio para grupos diferentes, não o nome de uma única nação invasora.', 'A queda de sistemas palaciais não significou desaparecimento completo das populações. Muitas comunidades se reorganizaram.'] },
    { match: /Israel|Judá|Bíblia Hebraica/i, simple: 'Israel e Judá foram reinos do Levante que surgiram em meio às transformações do início da Idade do Ferro. A Bíblia Hebraica é uma fonte indispensável, mas seus textos foram escritos e editados em períodos diferentes e possuem objetivos religiosos e políticos.', anchor: 'Levante, sobretudo entre os séculos X e VI a.C.', detail: ['Arqueologia e inscrições de povos vizinhos ajudam a confrontar e contextualizar narrativas bíblicas.', 'O reino de Israel foi conquistado pela Assíria em 722 a.C.; Judá caiu diante da Babilônia em 586 a.C.', 'O exílio babilônico e o período persa foram importantes na formação de tradições religiosas e identidades judaicas.'] },
    { match: /Assíria|Babilônia Neobabilônica/i, simple: 'Assíria e Babilônia foram centros políticos diferentes da Mesopotâmia. O Império Neoassírio construiu um sistema militar e administrativo expansivo; depois de sua queda, a Babilônia voltou a ocupar papel imperial.', anchor: 'Oriente Próximo, sobretudo séculos IX a VI a.C.', detail: ['A Assíria combinava guerra, deportações, administração provincial e propaganda real.', 'Deportação não significava necessariamente extermínio: também era usada para redistribuir população e trabalho.', 'O Império Neobabilônico, associado a Nabucodonosor II, foi posteriormente conquistado por Ciro da Pérsia.'] },
    { match: /Minoicos|Creta/i, simple: 'Antes das pólis gregas existirem, Creta abrigou sociedades palaciais que hoje chamamos de minoicas. Elas participavam de redes comerciais do Egeu e deixaram palácios, afrescos e sistemas de escrita.', anchor: 'Creta, aproximadamente 2000 a 1450 a.C. para o auge palacial.', detail: ['Knossos é o sítio mais famoso, mas Creta possuía vários centros.', 'Linear A ainda não foi decifrada, o que limita o que sabemos diretamente sobre língua e administração.', 'O nome minoico foi criado por arqueólogos modernos e deriva do mito do rei Minos.'] },
    { match: /Micênicos|Linear B/i, simple: 'No continente grego, sociedades que chamamos de micênicas organizaram palácios fortificados e redes administrativas. A escrita Linear B registra uma forma antiga da língua grega.', anchor: 'Grécia continental e Egeu, principalmente entre 1600 e 1200 a.C.', detail: ['Micenas, Pilos e Tirinto eram centros diferentes, não capitais de um Estado grego unificado.', 'Tabletes de Linear B registram bens, trabalhadores, terras e oferendas, por isso mostram sobretudo administração palacial.', 'Esse mundo entrou em crise por volta de 1200 a.C., séculos antes da forma final da Ilíada e da Odisseia.'] },
    { match: /Ilíada|Odisseia|Homero/i, simple: 'Ilíada e Odisseia são poemas épicos formados por uma longa tradição oral e registrados por escrito muitos séculos depois do mundo micênico. Eles preservam memórias, valores e imagens do passado, mas não são reportagens sobre a Guerra de Troia.', anchor: 'Tradições consolidadas sobretudo nos séculos VIII e VII a.C., olhando para um passado heroico mais antigo.', detail: ['A Ilíada gira em torno da ira de Aquiles durante a guerra em Troia, não narra a guerra inteira.', 'A Odisseia acompanha o retorno de Odisseu e discute hospitalidade, identidade, poder doméstico e memória.', 'Arqueologia de Troia e documentos hititas mostram que havia conflitos e contatos na região, mas não provam a narrativa épica tal como chegou até nós.', 'Os poemas dizem muito sobre os valores e tensões das comunidades que os transmitiram.'] },
    { match: /formação das pólis|pólis/i, simple: 'A pólis era uma comunidade política formada por cidadãos, instituições, cultos e território. Atenas e Esparta eram pólis, mas organizavam sociedade e poder de formas muito diferentes.', anchor: 'Mundo grego, sobretudo entre os séculos VIII e IV a.C.', detail: ['A pólis não era apenas a área urbana.', 'Cidadania era restrita e excluía grande parte da população.', 'Colonização grega criou novas comunidades no Mediterrâneo e no Mar Negro, sem formar um império grego unificado.'] },
    { match: /^Atenas|democracia ateniense/i, simple: 'A democracia ateniense permitia participação direta de cidadãos homens em assembleias e tribunais. Foi uma experiência política importante, mas estava apoiada numa sociedade que excluía mulheres, escravizados e estrangeiros residentes.', anchor: 'Atenas, principalmente séculos V e IV a.C.', detail: ['Reformas associadas a Sólon e Clístenes mudaram instituições antes do auge democrático.', 'A Assembleia decidia diretamente diversas questões políticas.', 'Democracia e império coexistiram: Atenas dominou aliados por meio da Liga de Delos.'] },
    { match: /^Esparta|espartanos/i, simple: 'Esparta organizou sua cidadania masculina em torno de treinamento militar e participação política, apoiada pelo trabalho compulsório dos hilotas. A imagem de uma cidade perfeitamente militarizada foi ampliada por autores antigos e modernos.', anchor: 'Lacônia e Messênia, principalmente período arcaico e clássico.', detail: ['Hilotas eram populações submetidas que sustentavam a economia espartana.', 'Esparta possuía reis, gerúsia, éforos e assembleia, não uma simples ditadura de um comandante.', 'A chamada miragem espartana lembra que muito do que sabemos foi escrito por observadores externos fascinados pela cidade.'] },
    { match: /Guerras Persas/i, simple: 'As Guerras Persas foram conflitos entre o Império Aquemênida e várias pólis gregas. Não foram uma guerra simples entre Grécia e Pérsia, porque as cidades gregas não formavam uma unidade política e algumas apoiaram os persas.', anchor: 'Principalmente 499 a 449 a.C.', detail: ['Maratona, Termópilas, Salamina e Plateia são episódios centrais, mas precisam ser inseridos numa disputa imperial mais ampla.', 'Heródoto é fonte fundamental e também autor literário com escolhas narrativas próprias.', 'A vitória ajudou Atenas a ampliar sua liderança no Egeu.'] },
    { match: /Guerra do Peloponeso/i, simple: 'A Guerra do Peloponeso foi uma longa disputa entre alianças lideradas por Atenas e Esparta. Ela mostrou como rivalidade, medo, recursos e política interna podiam transformar conflitos locais em guerra prolongada.', anchor: '431 a 404 a.C.', detail: ['Atenas possuía poder naval e um império de aliados tributários.', 'Esparta liderava uma coalizão terrestre e recebeu apoio persa na fase final.', 'Tucídides é uma fonte central, mas sua obra também é uma interpretação construída do conflito.'] },
    { match: /Alexandre|mundo helenístico/i, simple: 'Alexandre da Macedônia conquistou o Império Persa em poucos anos, mas seu império se fragmentou logo após sua morte. O período helenístico surgiu dessa fragmentação e das novas conexões entre Mediterrâneo, Egito e Ásia.', anchor: 'Conquistas de Alexandre entre 334 e 323 a.C.; reinos helenísticos até a expansão romana.', detail: ['Macedônios não eram simplesmente Atenas ou Esparta ampliadas.', 'Ptolomeus, Selêucidas e outras dinastias governaram populações culturalmente diversas.', 'Helenização não foi cópia unilateral da cultura grega: houve adaptações e misturas locais.'] },
    { match: /República Romana/i, simple: 'Depois do período monárquico, Roma construiu uma República em que magistrados, Senado e assembleias dividiam o poder. Era uma república, mas não uma democracia igualitária moderna.', anchor: 'Tradicionalmente 509 a 27 a.C.', detail: ['Conflitos entre patrícios e plebeus alteraram direitos e instituições.', 'A expansão militar transformou economia, escravidão, competição aristocrática e política.', 'As instituições funcionavam por equilíbrio informal de prestígio, costumes e alianças, não por uma constituição escrita única.'] },
    { match: /Guerras Púnicas|Cartago/i, simple: 'Roma e Cartago disputaram poder no Mediterrâneo ocidental em três grandes guerras. A vitória romana abriu caminho para expansão territorial e trouxe enormes recursos, escravizados e tensões sociais para a República.', anchor: '264 a 146 a.C.', detail: ['Aníbal atravessou os Alpes e venceu grandes batalhas, mas não destruiu a capacidade política romana.', 'A guerra ocorreu em vários teatros, não apenas na Itália.', 'A destruição de Cartago em 146 a.C. simboliza o novo peso imperial de Roma.'] },
    { match: /César|Augusto|fim da República/i, simple: 'A crise da República não aconteceu porque um único homem destruiu um sistema estável. Décadas de expansão, guerras civis, competição aristocrática e exércitos ligados a comandantes enfraqueceram acordos políticos.', anchor: 'Sobretudo do século I a.C. até 27 a.C.', detail: ['Júlio César venceu uma guerra civil e foi assassinado em 44 a.C.', 'Novas guerras levaram à vitória de Otaviano sobre Marco Antônio e Cleópatra.', 'Em 27 a.C., Otaviano recebeu o título Augusto e construiu um regime monárquico que preservava formas republicanas.'] },
    { match: /Império Romano|Principado/i, simple: 'O Império Romano não era apenas Roma governando províncias pela força. Ele dependia de exércitos, impostos, cidades, elites locais, cidadania e redes de circulação que funcionavam de maneiras diferentes em cada região.', anchor: 'Do governo de Augusto em 27 a.C. à Antiguidade Tardia, com transformações profundas ao longo do período.', detail: ['Imperadores precisavam negociar com Senado, exército e elites provinciais.', 'A cidadania romana foi ampliada e chegou à maioria dos homens livres do império em 212.', 'Romanização é hoje tratada como processo de negociação e adaptação, não simples substituição cultural.'] },
    { match: /cristianismo|cristianização/i, simple: 'O cristianismo começou como um movimento judaico no Império Romano e se espalhou por redes urbanas do Mediterrâneo. Durante séculos, comunidades cristãs foram diversas e disputaram crenças, autoridade e práticas.', anchor: 'Do século I em diante, com transformação decisiva no século IV.', detail: ['Perseguições existiram, mas foram descontínuas e variaram por período e região.', 'Constantino favoreceu o cristianismo no século IV, mas não transformou imediatamente o império inteiro em cristão.', 'Concílios e debates teológicos também eram disputas sobre instituições e autoridade.'] },
    { match: /queda de Roma|crise do século III|fim do Império Romano/i, simple: 'O Império Romano do Ocidente não caiu numa única noite. Entre os séculos III e V, mudanças militares, fiscais, políticas e migratórias transformaram o Estado romano enquanto novos reinos se formavam dentro de antigos territórios imperiais.', anchor: 'Principalmente séculos III a V no Ocidente; o Império Romano do Oriente continuou por quase mil anos.', detail: ['476 é uma data útil, mas não encerra toda a história romana.', 'Povos chamados bárbaros já mantinham relações de guerra, comércio e serviço militar com Roma.', 'No Oriente, Constantinopla preservou instituições romanas e formou o que hoje chamamos de Império Bizantino.'] },
    { match: /Bizâncio|Justiniano|Constantinopla/i, simple: 'Bizâncio é o nome moderno dado ao Império Romano que continuou governado a partir de Constantinopla. Seus habitantes se chamavam romanos.', anchor: 'Império Romano do Oriente, do século IV até 1453.', detail: ['Justiniano tentou recuperar territórios do antigo Ocidente no século VI.', 'O império combinou direito romano, cristianismo e língua grega em proporções que mudaram ao longo do tempo.', 'Bizâncio conectava Mediterrâneo, Balcãs, Oriente Próximo e rotas para o Mar Negro.'] },
    { match: /feudalismo|senhorio|vassalagem/i, simple: 'Feudalismo não é uma palavra que descreve toda a Idade Média de forma automática. Historiadores a usaram para reunir relações entre nobres, terras, poder e dependência, mas hoje distinguem vassalagem política de senhorio sobre camponeses.', anchor: 'Europa ocidental medieval, com grande variação entre séculos e regiões.', detail: ['Vassalagem era uma relação entre elites livres; servidão dizia respeito a obrigações camponesas.', 'Reinos, cidades, Igreja e comunidades locais continuaram importantes.', 'O debate sobre se feudalismo é uma categoria útil faz parte do próprio estudo da Idade Média.'] },
    { match: /mundo islâmico|Maomé|califado/i, simple: 'O Islã surgiu na Arábia do século VII e rapidamente se tornou também uma força política. Depois da morte de Maomé, disputas sobre liderança contribuíram para a formação de diferentes tradições e dinastias.', anchor: 'Arábia e depois amplas áreas do Oriente Médio, Norte da África, Ásia Central e Península Ibérica a partir do século VII.', detail: ['Califados Rashidun, Omíada e Abássida tiveram estruturas e centros políticos distintos.', 'Sunismo e xiismo se formaram ao longo de processos históricos, não em um único evento instantâneo.', 'Cidades como Bagdá, Cairo, Córdoba e Damasco foram centros de comércio, administração e produção intelectual.'] },
    { match: /Cruzadas/i, simple: 'As Cruzadas foram campanhas militares legitimadas pela religião, mas também envolveram política, terra, comércio e rivalidades locais. Elas não podem ser resumidas como uma guerra contínua entre cristãos e muçulmanos.', anchor: 'Principalmente entre o final do século XI e o século XIII.', detail: ['A Primeira Cruzada conquistou Jerusalém em 1099 e criou Estados cruzados.', 'Cristãos orientais, judeus, muçulmanos e diferentes grupos europeus tiveram experiências distintas.', 'A Quarta Cruzada saqueou Constantinopla em 1204, mostrando que as alianças não seguiam uma divisão religiosa simples.'] },
    { match: /Peste Negra|crise do século XIV/i, simple: 'A Peste Negra foi uma pandemia devastadora que atingiu grande parte da Eurásia e do Norte da África. Sua importância histórica não está apenas no número de mortes, mas nas mudanças sociais provocadas por uma queda brusca da população.', anchor: 'Grande onda entre 1347 e 1353, com recorrências posteriores.', detail: ['A bactéria Yersinia pestis circulou por redes de mobilidade e comércio.', 'Escassez de mão de obra alterou salários, contratos e relações entre senhores e trabalhadores em muitas regiões.', 'Respostas incluíram religião, perseguições, medidas sanitárias e novas formas de administração urbana.'] },
    { match: /Renascimento/i, simple: 'Renascimento é o nome dado a movimentos culturais que valorizaram textos clássicos, novas formas artísticas e educação humanista. Isso não significa que a Idade Média tivesse esquecido completamente a Antiguidade.', anchor: 'Sobretudo cidades italianas dos séculos XIV e XV, com expansão para outras regiões europeias.', detail: ['Humanistas buscaram, editaram e compararam manuscritos antigos.', 'Patronos urbanos e cortes financiaram artistas e estudiosos.', 'Imprensa, comércio e circulação intelectual ajudaram a ampliar essas transformações.'] },
    { match: /Reforma Protestante|Lutero|Calvino/i, simple: 'A Reforma começou como crítica religiosa, mas rapidamente se tornou também uma crise política e institucional. Igrejas, príncipes, cidades e comunidades passaram a disputar quem podia definir a fé legítima.', anchor: 'Europa do século XVI, especialmente a partir de 1517.', detail: ['Lutero criticou práticas e autoridades da Igreja e encontrou proteção política no Sacro Império.', 'Calvinismo e outras correntes reformadas desenvolveram projetos próprios.', 'A Reforma Católica ou Contrarreforma reorganizou instituições católicas, ensino e disciplina religiosa.'] },
    { match: /absolutismo|monarquias absolutas/i, simple: 'Quando falamos em absolutismo, não significa que reis podiam fazer qualquer coisa. O termo descreve projetos de fortalecimento da monarquia, exército, impostos e administração, sempre negociados com elites e instituições.', anchor: 'Europa moderna, sobretudo séculos XVI a XVIII.', detail: ['Luís XIV é o exemplo mais conhecido, mas a França continuava cheia de privilégios e jurisdições locais.', 'Estados precisavam de crédito, burocracia e cooperação de elites para fazer guerra.', 'Parlamentos, cortes, municípios e igrejas podiam limitar ou negociar o poder régio.'] },
    { match: /expansão europeia|colonialismo|conquista da América/i, simple: 'A expansão marítima europeia conectou oceanos e sociedades de maneira cada vez mais intensa, mas não foi um encontro entre europeus ativos e povos passivos. Conquista e colonização dependeram de alianças locais, doenças, violência, negociação e trabalho.', anchor: 'A partir do século XV, envolvendo Atlântico, Índico, África, Américas e Ásia.', detail: ['Portugal e Espanha abriram rotas diferentes e depois foram acompanhados por outras potências.', 'Epidemias tiveram efeitos devastadores nas Américas, mas não explicam sozinhas a conquista.', 'Impérios coloniais dependiam de intermediários indígenas, africanos, asiáticos e mestiços.'] },
    { match: /América Pré-Colombiana|maias|astecas|incas/i, simple: 'As Américas antes de Colombo abrigavam sociedades muito diferentes, de comunidades móveis a grandes cidades e impérios. Maia, asteca e inca são apenas três exemplos dentro de uma história muito mais ampla.', anchor: 'Américas antes de 1492, com cronologias regionais de milhares de anos.', detail: ['Maias possuíam várias cidades e reinos, não um império único e permanente.', 'O Império Mexica ou Asteca era baseado em tributos e alianças no centro do México.', 'O Tawantinsuyu Inca organizou vasto território andino por estradas, trabalho obrigatório e administração.'] },
    { match: /escravidão atlântica|tráfico atlântico/i, simple: 'A escravidão atlântica transformou pessoas em propriedade legal e conectou economias de África, Europa e Américas. Milhões de africanos foram capturados, vendidos, transportados e obrigados a trabalhar, mas também resistiram, negociaram e construíram comunidades.', anchor: 'Principalmente séculos XVI a XIX no Atlântico.', detail: ['Sociedades africanas participaram do comércio em condições muito diferentes, sob pressões e disputas internas próprias.', 'A travessia atlântica foi uma etapa de altíssima mortalidade e violência.', 'Plantations, mineração, trabalho urbano e doméstico criaram experiências de escravidão distintas.', 'Abolição legal não eliminou racismo, desigualdade ou formas de coerção no pós-abolição.'] },
    { match: /Revolução Industrial/i, simple: 'A Revolução Industrial foi a transformação de como energia, máquinas, trabalho e produção se combinavam. Ela começou com maior intensidade na Grã-Bretanha e depois se espalhou de maneiras diferentes.', anchor: 'A partir da segunda metade do século XVIII, com expansão durante o século XIX.', detail: ['Carvão e máquina a vapor ampliaram a energia disponível para produção e transporte.', 'Fábricas mudaram disciplina de tempo e relações de trabalho, mas trabalho doméstico e oficinas continuaram existindo.', 'O debate sobre padrão de vida pergunta quem ganhou, quem perdeu e em qual momento da industrialização.'] },
    { match: /História do Capitalismo|origem do capitalismo|capitalismo/i, simple: 'Capitalismo não nasceu pronto em uma data única. Historiadores discutem como mercados, propriedade, trabalho assalariado, finanças, impérios e produção para lucro se combinaram ao longo de séculos.', anchor: 'Debate de longa duração, com transformações importantes entre os séculos XVI e XIX.', detail: ['Alguns autores destacam comércio e cidades; outros mudanças nas relações agrárias e no trabalho.', 'Escravidão, colonialismo e expansão atlântica fazem parte do debate sobre formação do capitalismo.', 'Industrialização transformou escala, produtividade e disciplina do trabalho, mas não criou todos os elementos do sistema do zero.'] },
    { match: /Marx e Engels|marxismo/i, simple: 'Marx e Engels tentaram explicar o capitalismo como um sistema histórico baseado em relações sociais, propriedade e trabalho assalariado. Eles não escreveram um manual único de como toda sociedade socialista deveria funcionar.', anchor: 'Europa do século XIX, especialmente a partir das décadas de 1840 e 1850.', detail: ['Classe social é analisada pela posição nas relações de produção, não apenas por renda.', 'Mais-valia procura explicar como lucro e acumulação se relacionam ao trabalho.', 'Materialismo histórico não significa que economia cause automaticamente tudo o que acontece na política ou cultura.'] },
    { match: /socialismo utópico|Fourier|Owen|Saint-Simon/i, simple: 'Antes do marxismo ganhar força, diversos pensadores já criticavam desigualdade, propriedade e competição. Saint-Simon, Fourier e Owen imaginaram comunidades e formas de organização cooperativa bastante diferentes entre si.', anchor: 'Europa entre o final do século XVIII e primeira metade do século XIX.', detail: ['O rótulo utópico foi popularizado pelos próprios Marx e Engels e deve ser usado com cuidado.', 'Robert Owen experimentou reformas industriais e comunidades cooperativas.', 'Essas correntes mostram que socialismo nunca foi uma única doutrina.'] },
    { match: /anarquismo|Bakunin|Kropotkin/i, simple: 'Anarquismo não significa ausência de organização. As correntes anarquistas criticam autoridade coercitiva e defendem formas de organização baseadas em associação voluntária, autogestão e ajuda mútua.', anchor: 'Movimentos modernos sobretudo a partir do século XIX.', detail: ['Proudhon, Bakunin e Kropotkin divergiam em propriedade, estratégia e organização.', 'Anarquistas tiveram presença forte em sindicatos e movimentos operários de vários países.', 'A relação com marxistas foi marcada por cooperação e conflitos, especialmente sobre Estado e partido.'] },
    { match: /social-democracia|Bernstein|revisionismo/i, simple: 'A social-democracia nasceu dentro do movimento socialista e passou a discutir se a transformação poderia ocorrer por eleições, sindicatos e reformas graduais, ou se seria necessária uma ruptura revolucionária.', anchor: 'Europa, principalmente do final do século XIX ao século XX.', detail: ['Eduard Bernstein defendeu revisão de expectativas revolucionárias do marxismo.', 'Partidos social-democratas cresceram junto com sindicatos e expansão do sufrágio.', 'No século XX, muitos passaram a defender Estado de bem-estar e economia mista.'] },
    { match: /Lenin|leninismo/i, simple: 'Lenin desenvolveu ideias sobre partido, imperialismo e revolução a partir das condições do Império Russo e do movimento socialista internacional. Leninismo é uma tradição posterior que sistematizou parte dessas ideias.', anchor: 'Império Russo e Europa, final do século XIX e primeiras décadas do século XX.', detail: ['O partido revolucionário deveria organizar militantes e intervenção política, mas a interpretação de centralismo mudou ao longo do tempo.', 'Em 1917, Lenin defendeu transferência de poder aos sovietes e ruptura com o Governo Provisório.', 'Depois da guerra civil, o novo Estado soviético enfrentou autoritarismo, crise econômica e debates internos profundos.'] },
    { match: /Revolução Russa|Outubro de 1917/i, simple: 'A Revolução Russa de 1917 teve duas grandes rupturas. Em fevereiro, o czar caiu; em outubro, os bolcheviques derrubaram o Governo Provisório. Entre esses momentos, sovietes, soldados, camponeses e partidos disputavam o futuro do país.', anchor: 'Rússia, 1917, seguida por guerra civil até o início da década de 1920.', detail: ['A Primeira Guerra Mundial agravou crise de abastecimento, legitimidade e disciplina militar.', 'Os sovietes eram conselhos de trabalhadores e soldados com poder político real em várias cidades.', 'Chamar Outubro de revolução ou golpe depende de como se definem participação popular, legalidade e transformação institucional, por isso é um debate historiográfico.'] },
    { match: /Stalin|stalinismo/i, simple: 'Stalin consolidou poder após a morte de Lenin e conduziu uma transformação rápida da economia e do Estado soviético. Industrialização acelerada ocorreu junto com coletivização forçada, fome, repressão e expurgos.', anchor: 'União Soviética, principalmente final dos anos 1920 até 1953.', detail: ['Planos Quinquenais priorizaram indústria pesada e metas centralizadas.', 'Coletivização alterou profundamente o campo e esteve ligada a violência e fome em várias regiões.', 'O Grande Terror dos anos 1930 atingiu quadros do partido, militares e milhões de cidadãos.', 'Historiadores discutem continuidades e rupturas entre Lenin e Stalin em vez de assumir uma resposta automática.'] },
    { match: /Mao|maoísmo|Grande Salto|Revolução Cultural/i, simple: 'O comunismo chinês se desenvolveu em condições diferentes das russas, com forte peso do campesinato e da guerra prolongada. Depois de 1949, Mao liderou campanhas que transformaram propriedade e poder, algumas com custos humanos enormes.', anchor: 'China, sobretudo da década de 1920 à morte de Mao em 1976.', detail: ['A vitória comunista ocorreu depois de guerra civil e guerra contra o Japão.', 'O Grande Salto Adiante tentou acelerar produção e contribuiu para uma fome catastrófica.', 'A Revolução Cultural mobilizou jovens e facções contra supostos inimigos políticos, produzindo violência e desorganização institucional.'] },
    { match: /imperialismo do século XIX|partilha da África/i, simple: 'No final do século XIX, potências europeias ampliaram controle territorial sobre África e Ásia. A expansão envolveu força militar, empresas, missões, diplomacia e competição entre impérios.', anchor: 'Sobretudo de 1870 a 1914.', detail: ['A Conferência de Berlim não dividiu sozinha a África, mas estabeleceu regras de competição entre potências.', 'Estados e sociedades africanas resistiram, negociaram e se adaptaram de formas diferentes.', 'Imperialismo também envolveu Índia, Sudeste Asiático, China e Pacífico, não apenas África.'] },
    { match: /Primeira Guerra Mundial/i, simple: 'A Primeira Guerra começou como uma crise europeia, mas virou guerra global porque impérios mobilizaram colônias, rotas marítimas, economias e milhões de soldados em vários continentes.', anchor: '1914 a 1918, com consequências políticas que avançam pelas décadas seguintes.', detail: ['O assassinato de Francisco Ferdinando desencadeou uma crise num sistema já marcado por alianças, militarização e rivalidades imperiais.', 'Frentes de trincheira foram importantes, mas também houve guerra no Oriente Médio, África, Cáucaso e mares.', 'O conflito derrubou os impérios Alemão, Austro-Húngaro, Otomano e Russo.'] },
    { match: /fascismo/i, simple: 'Fascismo foi uma resposta ultranacionalista e antidemocrática às crises do pós-guerra. Fascistas defendiam hierarquia, violência política, mobilização de massas e um Estado forte dirigido por uma liderança autoritária.', anchor: 'Europa do período entre guerras, com destaque para Itália a partir de 1922.', detail: ['O fascismo italiano de Mussolini é referência central, mas movimentos semelhantes assumiram formas nacionais diferentes.', 'Fascistas combateram socialistas, liberais e movimentos democráticos.', 'Chegada ao poder combinou violência de rua, apoio de elites e uso das próprias instituições existentes.'] },
    { match: /nazismo|Hitler/i, simple: 'Nazismo foi uma forma radical de fascismo que colocou racismo biológico e antissemitismo no centro do projeto político. O regime buscava reorganizar a sociedade alemã e conquistar espaço territorial por guerra.', anchor: 'Alemanha, principalmente 1933 a 1945.', detail: ['Hitler chegou ao governo por nomeação dentro de uma crise política e depois destruiu rapidamente instituições democráticas.', 'Leis raciais transformaram perseguição em política estatal.', 'Expansionismo e ideologia racial ajudaram a conduzir à guerra de conquista e ao genocídio.'] },
    { match: /Holocausto/i, simple: 'O Holocausto foi o assassinato sistemático de cerca de seis milhões de judeus europeus pelo regime nazista e seus colaboradores. O processo evoluiu de exclusão e perseguição para deportação e extermínio em massa.', anchor: 'Europa sob domínio nazista, sobretudo 1941 a 1945, precedido por perseguições desde 1933.', detail: ['Judeus foram o principal alvo de um projeto genocida; Roma e Sinti, pessoas com deficiência e outros grupos também sofreram perseguição e assassinato.', 'Fuzilamentos em massa no Leste fizeram parte do genocídio antes e durante a operação dos campos de extermínio.', 'Estudar o Holocausto exige fontes de vítimas, perpetradores e testemunhas, sem transformar sofrimento em abstração estatística.'] },
    { match: /Segunda Guerra Mundial/i, simple: 'A Segunda Guerra foi uma guerra global entre coalizões de Estados e impérios. Na Europa, expansão nazista foi central; na Ásia, a guerra entre Japão e China já estava em curso antes de 1939.', anchor: 'Conflitos decisivos de 1937 a 1945 na Ásia e de 1939 a 1945 na Europa.', detail: ['Alemanha invadiu a Polônia em 1939; Japão já travava guerra em larga escala na China desde 1937.', 'A entrada da União Soviética e dos Estados Unidos foi decisiva para o equilíbrio militar.', 'Bombardeios, ocupações, genocídios e deslocamentos atingiram civis em escala gigantesca.'] },
    { match: /Guerra Fria/i, simple: 'A Guerra Fria foi uma disputa mundial entre blocos liderados por Estados Unidos e União Soviética. Eles evitaram guerra direta total entre si, mas apoiaram conflitos, governos e movimentos em várias regiões.', anchor: 'Aproximadamente de 1945 a 1991.', detail: ['Armas nucleares criaram um equilíbrio baseado no risco de destruição mútua.', 'Alemanha, Coreia, Vietnã, Cuba, Afeganistão e várias regiões do chamado Terceiro Mundo tornaram-se pontos de conflito.', 'Países não alinhados tentaram construir projetos próprios, por isso o mundo não pode ser reduzido a dois blocos passivos.'] },
    { match: /descolonização/i, simple: 'Descolonização foi o processo pelo qual impérios europeus perderam controle formal sobre territórios na Ásia, África e outras regiões. Independência política não eliminou automaticamente dependência econômica, fronteiras coloniais ou conflitos internos.', anchor: 'Principalmente entre as décadas de 1940 e 1970, com trajetórias anteriores e posteriores.', detail: ['Índia tornou-se independente em 1947, acompanhada da violenta Partição.', 'Argélia conquistou independência da França após uma guerra brutal.', 'Movimentos africanos combinaram nacionalismo, pan-africanismo, socialismo e outras correntes.'] },
    { match: /Brasil indígena|povos indígenas/i, simple: 'O território que se tornaria o Brasil já era habitado por milhões de pessoas pertencentes a povos com línguas, economias e organizações políticas diferentes. A colonização não começa uma história vazia.', anchor: 'Milhares de anos antes de 1500 até o presente.', detail: ['Tupi, Macro-Jê e muitas outras famílias linguísticas não representam povos homogêneos.', 'Contato europeu trouxe guerras, epidemias, alianças, escravização e deslocamentos.', 'Povos indígenas continuaram atuando politicamente durante Colônia, Império e República.'] },
    { match: /açúcar|plantation.*Brasil|Brasil colonial/i, simple: 'A colonização portuguesa no Brasil se estruturou por interesses diferentes ao longo do território. A produção açucareira se tornou central em partes do Nordeste e dependeu cada vez mais do trabalho de africanos escravizados.', anchor: 'América portuguesa, sobretudo séculos XVI e XVII para o auge inicial do açúcar.', detail: ['Engenhos reuniam terra, equipamentos, trabalhadores e redes de crédito.', 'A economia colonial não era apenas exportação: havia produção de alimentos, pecuária e mercados internos.', 'Colonização dependia de violência, negociação com povos indígenas e integração ao comércio atlântico.'] },
    { match: /mineração|ouro.*Brasil/i, simple: 'A descoberta de ouro e diamantes deslocou população e recursos para o centro-sul da América portuguesa. A mineração ampliou urbanização, circulação interna e presença fiscal da Coroa.', anchor: 'Principalmente Minas Gerais, Goiás e Mato Grosso no século XVIII.', detail: ['Mineração continuou baseada em trabalho escravizado.', 'Cidades e vilas criaram mercados mais diversificados do que áreas rurais de plantation.', 'Impostos como o quinto ajudaram a alimentar conflitos entre colonos e administração portuguesa.'] },
    { match: /Independência do Brasil/i, simple: 'A independência brasileira não foi apenas o grito de 7 de setembro. Ela resultou da crise do império português, da transferência da corte ao Rio, da Revolução do Porto e de disputas regionais sobre quem controlaria o novo Estado.', anchor: 'Processo entre 1808 e 1825, com 1822 como marco político central.', detail: ['A presença da corte desde 1808 transformou instituições e economia do centro do império.', 'Províncias reagiram de maneiras diferentes à separação de Portugal.', 'A independência manteve monarquia e escravidão, ao contrário de outras revoluções americanas.'] },
    { match: /abolição.*Brasil|Lei Áurea|pós-abolição/i, simple: 'A escravidão brasileira acabou legalmente em 1888 depois de décadas de resistência de escravizados, fugas, ações judiciais, mobilização abolicionista e mudanças políticas. A Lei Áurea foi um marco, não a causa única da abolição.', anchor: 'Brasil do século XIX, com abolição legal em 13 de maio de 1888.', detail: ['Tráfico atlântico foi proibido em 1850, mas a escravidão interna continuou.', 'Movimentos negros e redes de liberdade tiveram papel ativo no processo.', 'O pós-abolição não criou políticas amplas de reparação, terra ou integração social, e desigualdades raciais permaneceram profundas.'] },
    { match: /Vargas|Estado Novo/i, simple: 'Getúlio Vargas governou o Brasil em fases diferentes, primeiro após a Revolução de 1930 e depois como presidente eleito nos anos 1950. O Estado Novo foi a fase ditatorial entre 1937 e 1945.', anchor: 'Brasil, especialmente 1930 a 1945 e 1951 a 1954.', detail: ['O período ampliou intervenção estatal, legislação trabalhista e industrialização.', 'Direitos trabalhistas coexistiram com controle sindical e repressão política.', 'Vargas construiu formas modernas de comunicação política e relação direta com trabalhadores urbanos.'] },
    { match: /ditadura militar|golpe de 1964/i, simple: 'O golpe de 1964 derrubou o governo de João Goulart e iniciou uma ditadura militar que durou até 1985. O regime manteve algumas instituições formais, mas restringiu direitos, perseguiu opositores e controlou a competição política.', anchor: 'Brasil, 1964 a 1985.', detail: ['Atos Institucionais ampliaram poderes do Executivo e reduziram garantias constitucionais.', 'O AI-5, de 1968, marcou forte intensificação da repressão.', 'Crescimento econômico do chamado milagre conviveu com concentração de renda, censura, tortura e endividamento.'] },
    { match: /Nova República|redemocratização/i, simple: 'A redemocratização brasileira foi um processo gradual de abertura política, mobilização social e reconstrução institucional. A Constituição de 1988 ampliou direitos e definiu a base do regime democrático atual.', anchor: 'Principalmente do final dos anos 1970 ao final dos anos 1980, com continuidade no período posterior.', detail: ['Anistia, reorganização partidária, greves e movimentos sociais pressionaram o regime.', 'Diretas Já não conseguiu eleição presidencial direta em 1985, mas mostrou forte mobilização pública.', 'A História do Tempo Presente exige cuidado porque fontes, memórias e disputas políticas continuam em transformação.'] },
    { match: /historiografia/i, simple: 'Historiografia é estudar como a História foi escrita. O foco não é apenas descobrir o que aconteceu, mas entender por que historiadores diferentes fazem perguntas diferentes e chegam a interpretações distintas.', anchor: 'É uma prática que atravessa todo o curso.', detail: ['Toda obra histórica seleciona problemas, fontes e escalas.', 'Mudanças sociais e intelectuais alteram as perguntas feitas ao passado.', 'Discordância historiográfica não significa que qualquer opinião vale: interpretações precisam ser sustentadas por fontes e método.'] },
    { match: /metodologia|pesquisa histórica/i, simple: 'Pesquisa histórica começa com uma pergunta que pode ser investigada, não com um tema amplo. Depois o historiador constrói um conjunto de fontes, conhece o debate existente e testa uma interpretação contra as evidências.', anchor: 'Método transversal a todas as épocas.', detail: ['Fonte não fala sozinha: é preciso perguntar quem produziu, para quem, com qual objetivo e o que foi silenciado.', 'Bibliografia serve para entrar em uma conversa, não apenas para colecionar citações.', 'Uma boa conclusão responde ao problema e também reconhece limites do que as fontes permitem afirmar.'] }
  ];

  const guideFor = title => GUIDE_RULES.find(rule => rule.match.test(title || '')) || null;

  function relatedEvents(courseId, lessonTitle, limit = 3) {
    const lessonTokens = new Set(tokens(lessonTitle));
    return (timeline.events || [])
      .filter(event => (event.courses || []).includes(courseId))
      .map(event => {
        const hay = new Set(tokens(`${event.title} ${event.summary}`));
        let score = 0;
        lessonTokens.forEach(token => { if (hay.has(token)) score += 2; });
        return { ...event, score };
      })
      .sort((a, b) => b.score - a.score)
      .slice(0, limit);
  }

  function fallbackSimple(lesson) {
    const concepts = (lesson.concepts || []).slice(0, 3);
    const conceptText = concepts.length ? ` Preste atenção especialmente em ${concepts.join(', ')}.` : '';
    return `Nesta aula, a meta é entender ${lesson.title} como um processo histórico, não decorar um nome isolado. Pergunte quem participa, em que contexto isso acontece e o que muda antes e depois.${conceptText}`;
  }

  function glossaryFor(lesson) {
    return (lesson.concepts || []).map(term => {
      const key = String(term).toLocaleLowerCase('pt-BR');
      return glossary[key] ? { term, definition: glossary[key] } : null;
    }).filter(Boolean).slice(0, 6);
  }

  function addCourseMap(course, detail) {
    if (document.querySelector('[data-course-map]')) return;
    const header = document.querySelector('.page-header');
    if (!header) return;

    const events = (timeline.events || []).filter(event => (event.courses || []).includes(course.id)).slice(0, 7);
    const questions = (detail?.modules || []).flatMap(module => module.questions || []).slice(0, 5);
    const first = events[0]?.date;
    const last = events[events.length - 1]?.date;
    const period = first && last && first !== last ? `${first} → ${last}` : (first || 'Cronologia varia conforme o módulo');

    const section = document.createElement('section');
    section.className = 'course-topic-map';
    section.dataset.courseMap = 'true';
    section.innerHTML = `
      <div class="eyebrow">Mapa da disciplina</div>
      <div class="course-map-grid">
        <div><span>Período</span><strong>${esc(period)}</strong></div>
        <div><span>Área</span><strong>${esc(course.area)}</strong></div>
        <div><span>Fio condutor</span><strong>${esc((detail?.intro || course.summary || '').split('. ')[0])}</strong></div>
      </div>
      ${questions.length ? `<details class="course-map-details"><summary>Perguntas que organizam o tema</summary><ol>${questions.map(q => `<li>${esc(q)}</li>`).join('')}</ol></details>` : ''}
      ${events.length ? `<details class="course-map-details"><summary>Marcos para se localizar no tempo</summary><div class="course-map-events">${events.map(event => `<article><b>${esc(event.date)}</b><span>${esc(event.title)}</span><p>${esc(event.summary)}</p></article>`).join('')}</div></details>` : ''}
    `;
    header.after(section);
  }

  function decorateLesson(card, course, lesson, index) {
    const body = card.querySelector('.lesson-body');
    if (!body || body.querySelector('[data-pedagogy]')) return;

    const guide = guideFor(lesson.title);
    const simple = guide?.simple || fallbackSimple(lesson);
    const events = relatedEvents(course.id, lesson.title, 2);
    const terms = glossaryFor(lesson);

    const simpleBox = document.createElement('section');
    simpleBox.className = 'plain-history';
    simpleBox.dataset.pedagogy = 'true';
    simpleBox.innerHTML = `
      <div class="eyebrow">Em termos simples</div>
      <p>${esc(simple)}</p>
      ${guide?.anchor ? `<div class="history-anchor"><span>Quando e onde</span><strong>${esc(guide.anchor)}</strong></div>` : ''}
    `;

    const opening = body.querySelector('.lesson-opening');
    if (opening) {
      const label = opening.querySelector('.eyebrow');
      if (label) label.textContent = 'Contexto histórico';
      body.insertBefore(simpleBox, opening);
    } else {
      body.prepend(simpleBox);
    }

    const concepts = body.querySelector('.concepts');
    const depth = document.createElement('details');
    depth.className = 'history-depth';
    depth.innerHTML = `
      <summary>Aprofundar este tema</summary>
      <div class="history-depth-body">
        ${guide?.detail?.length ? guide.detail.map(p => `<p>${esc(p)}</p>`).join('') : `<p>${esc((lesson.explanation || [])[1] || 'Relacione este assunto com o que veio antes e observe quais mudanças políticas, sociais, econômicas e culturais estão em jogo.')}</p>`}
        ${events.length ? `<div class="history-mini-timeline"><div class="eyebrow">Na linha do tempo</div>${events.map(event => `<div><b>${esc(event.date)}</b><span>${esc(event.title)}</span></div>`).join('')}</div>` : ''}
      </div>
    `;
    if (concepts) concepts.after(depth); else body.appendChild(depth);

    if (terms.length) {
      const vocab = document.createElement('details');
      vocab.className = 'history-vocab';
      vocab.innerHTML = `<summary>Palavras que você precisa entender</summary><dl>${terms.map(item => `<div><dt>${esc(item.term)}</dt><dd>${esc(item.definition)}</dd></div>`).join('')}</dl>`;
      depth.after(vocab);
    }

    const question = lesson.questions?.[0];
    if (question) {
      const checkpoint = document.createElement('aside');
      checkpoint.className = 'history-checkpoint';
      checkpoint.innerHTML = `<div class="eyebrow">Antes de seguir</div><p>Se você consegue responder com suas próprias palavras, a base desta aula está firme:</p><strong>${esc(question)}</strong>`;
      const reading = body.querySelector('.reading-callout');
      if (reading) body.insertBefore(checkpoint, reading);
      else body.appendChild(checkpoint);
    }
  }

  function decorate() {
    const p = route();
    if (p[0] !== 'course' || !p[1]) return;
    const course = courseById(p[1]);
    if (!course) return;
    const detail = state.content?.[course.id];
    if (!detail) return;

    addCourseMap(course, detail);
    document.querySelectorAll('.lesson-card').forEach((card, index) => {
      const lesson = detail.modules?.[index];
      if (lesson) decorateLesson(card, course, lesson, index);
    });
  }

  async function init() {
    try {
      const [glossaryResponse, timelineResponse] = await Promise.all([
        fetch('./history-glossary.json', { cache: 'no-store' }),
        fetch('./timeline.json', { cache: 'no-store' })
      ]);
      if (glossaryResponse.ok) glossary = await glossaryResponse.json();
      if (timelineResponse.ok) timeline = await timelineResponse.json();
    } catch {}

    const wait = () => {
      if (courses().length >= 30) {
        decorate();
        const app = document.getElementById('app');
        if (app) new MutationObserver(() => decorate()).observe(app, { childList: true, subtree: true });
        addEventListener('hashchange', () => setTimeout(decorate, 160));
        return;
      }
      setTimeout(wait, 100);
    };
    wait();
  }

  init();
})();
